-- Examcenter Pro Assessment Suite (additive)
CREATE TABLE IF NOT EXISTS pro_feature_catalog (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,feature_code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description TEXT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_question_bank_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id INT NOT NULL,topic VARCHAR(180) NULL,subtopic VARCHAR(180) NULL,difficulty VARCHAR(30) NULL,bloom_level VARCHAR(50) NULL,learning_objective VARCHAR(255) NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',version_no INT UNSIGNED NOT NULL DEFAULT 1,parent_item_id BIGINT UNSIGNED NULL,author_person_id BIGINT UNSIGNED NULL,reviewer_person_id BIGINT UNSIGNED NULL,metadata JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_qb_question(question_id),INDEX idx_pro_qb_topic(topic),INDEX idx_pro_qb_status(status),CONSTRAINT fk_pro_qb_question FOREIGN KEY(question_id) REFERENCES new_questions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_qb_parent FOREIGN KEY(parent_item_id) REFERENCES pro_question_bank_items(id) ON DELETE SET NULL,CONSTRAINT fk_pro_qb_author FOREIGN KEY(author_person_id) REFERENCES people(id) ON DELETE SET NULL,CONSTRAINT fk_pro_qb_reviewer FOREIGN KEY(reviewer_person_id) REFERENCES people(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_question_collections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,code VARCHAR(100) NOT NULL,name VARCHAR(255) NOT NULL,description TEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_by_person_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_collection(institution_id,code),CONSTRAINT fk_pro_collection_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_collection_creator FOREIGN KEY(created_by_person_id) REFERENCES people(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_question_collection_items (collection_id BIGINT UNSIGNED NOT NULL,bank_item_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(collection_id,bank_item_id),CONSTRAINT fk_pro_collection_item_collection FOREIGN KEY(collection_id) REFERENCES pro_question_collections(id) ON DELETE CASCADE,CONSTRAINT fk_pro_collection_item_item FOREIGN KEY(bank_item_id) REFERENCES pro_question_bank_items(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_blueprints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,description TEXT NULL,total_items INT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'draft',version_no INT UNSIGNED NOT NULL DEFAULT 1,created_by_person_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_pro_blueprint_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_blueprint_creator FOREIGN KEY(created_by_person_id) REFERENCES people(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_blueprint_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,blueprint_id BIGINT UNSIGNED NOT NULL,collection_id BIGINT UNSIGNED NULL,topic VARCHAR(180) NULL,difficulty VARCHAR(30) NULL,bloom_level VARCHAR(50) NULL,item_count INT UNSIGNED NOT NULL,marks_each DECIMAL(8,2) NULL,sort_order INT NOT NULL DEFAULT 0,metadata JSON NULL,CONSTRAINT fk_pro_rule_blueprint FOREIGN KEY(blueprint_id) REFERENCES pro_blueprints(id) ON DELETE CASCADE,CONSTRAINT fk_pro_rule_collection FOREIGN KEY(collection_id) REFERENCES pro_question_collections(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_blueprint_assemblies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,blueprint_id BIGINT UNSIGNED NOT NULL,test_id INT NULL,seed VARCHAR(120) NULL,status VARCHAR(30) NOT NULL DEFAULT 'generated',generated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,metadata JSON NULL,CONSTRAINT fk_pro_assembly_blueprint FOREIGN KEY(blueprint_id) REFERENCES pro_blueprints(id) ON DELETE CASCADE,CONSTRAINT fk_pro_assembly_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_blueprint_assembly_items (assembly_id BIGINT UNSIGNED NOT NULL,bank_item_id BIGINT UNSIGNED NOT NULL,sequence_no INT UNSIGNED NOT NULL,PRIMARY KEY(assembly_id,bank_item_id),UNIQUE KEY uq_pro_assembly_sequence(assembly_id,sequence_no),CONSTRAINT fk_pro_assembly_item_assembly FOREIGN KEY(assembly_id) REFERENCES pro_blueprint_assemblies(id) ON DELETE CASCADE,CONSTRAINT fk_pro_assembly_item_bank FOREIGN KEY(bank_item_id) REFERENCES pro_question_bank_items(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_item_analysis (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,question_id INT NOT NULL,sample_size INT UNSIGNED NOT NULL DEFAULT 0,difficulty_index DECIMAL(7,4) NULL,discrimination_index DECIMAL(7,4) NULL,facility_index DECIMAL(7,4) NULL,option_stats JSON NULL,reliability_contribution DECIMAL(7,4) NULL,recommendation VARCHAR(50) NULL,computed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_item_analysis(test_id,question_id),CONSTRAINT fk_pro_item_analysis_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE,CONSTRAINT fk_pro_item_analysis_question FOREIGN KEY(question_id) REFERENCES new_questions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_secure_exam_policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,fullscreen_required TINYINT(1) NOT NULL DEFAULT 1,block_copy_paste TINYINT(1) NOT NULL DEFAULT 1,block_context_menu TINYINT(1) NOT NULL DEFAULT 1,detect_focus_loss TINYINT(1) NOT NULL DEFAULT 1,detect_visibility_change TINYINT(1) NOT NULL DEFAULT 1,detect_multi_monitor TINYINT(1) NOT NULL DEFAULT 0,max_violations INT UNSIGNED NOT NULL DEFAULT 3,auto_pause_on_violation TINYINT(1) NOT NULL DEFAULT 0,terminate_on_threshold TINYINT(1) NOT NULL DEFAULT 0,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_secure_policy_test(test_id),CONSTRAINT fk_pro_secure_policy_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_exam_security_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,student_id INT NULL,attempt_id INT NULL,event_type VARCHAR(80) NOT NULL,severity VARCHAR(20) NOT NULL DEFAULT 'info',evidence JSON NULL,occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed TINYINT(1) NOT NULL DEFAULT 0,reviewed_by INT NULL,reviewed_at DATETIME NULL,review_decision VARCHAR(50) NULL,review_note TEXT NULL,INDEX idx_pro_security_test(test_id,occurred_at),CONSTRAINT fk_pro_security_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE,CONSTRAINT fk_pro_security_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_pro_security_attempt FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE SET NULL,CONSTRAINT fk_pro_security_reviewer FOREIGN KEY(reviewed_by) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_exam_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,institution_id BIGINT UNSIGNED NOT NULL,campus_id BIGINT UNSIGNED NULL,room_name VARCHAR(180) NULL,session_code VARCHAR(100) NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'scheduled',capacity INT UNSIGNED NULL,notes TEXT NULL,created_by_admin_id INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_exam_session_code(session_code),CONSTRAINT fk_pro_session_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE,CONSTRAINT fk_pro_session_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_session_creator FOREIGN KEY(created_by_admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_exam_session_candidates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,student_id INT NULL,person_id BIGINT UNSIGNED NULL,seat_no VARCHAR(50) NULL,checkin_at DATETIME NULL,checkout_at DATETIME NULL,status VARCHAR(30) NOT NULL DEFAULT 'registered',incident_count INT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_pro_session_candidate_student(session_id,student_id),CONSTRAINT fk_pro_candidate_session FOREIGN KEY(session_id) REFERENCES pro_exam_sessions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_candidate_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_pro_candidate_person FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_invigilators (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NULL,admin_id INT NULL,role_code VARCHAR(50) NOT NULL DEFAULT 'invigilator',checked_in_at DATETIME NULL,UNIQUE KEY uq_pro_invigilator(session_id,person_id,admin_id),CONSTRAINT fk_pro_invigilator_session FOREIGN KEY(session_id) REFERENCES pro_exam_sessions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_invigilator_person FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE SET NULL,CONSTRAINT fk_pro_invigilator_admin FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_session_incidents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,candidate_id BIGINT UNSIGNED NULL,incident_type VARCHAR(80) NOT NULL,severity VARCHAR(20) NOT NULL DEFAULT 'medium',description TEXT NULL,action_taken VARCHAR(100) NULL,recorded_by_admin_id INT NULL,recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_pro_incident_session FOREIGN KEY(session_id) REFERENCES pro_exam_sessions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_incident_candidate FOREIGN KEY(candidate_id) REFERENCES pro_exam_session_candidates(id) ON DELETE SET NULL,CONSTRAINT fk_pro_incident_admin FOREIGN KEY(recorded_by_admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_certificate_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,title VARCHAR(255) NOT NULL,body_template LONGTEXT NULL,logo_path VARCHAR(500) NULL,settings JSON NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_pro_cert_template_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_certificates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,template_id BIGINT UNSIGNED NULL,student_id INT NULL,person_id BIGINT UNSIGNED NULL,test_id INT NULL,certificate_no VARCHAR(100) NOT NULL,recipient_name VARCHAR(255) NOT NULL,issued_at DATETIME NOT NULL,expires_at DATETIME NULL,status VARCHAR(30) NOT NULL DEFAULT 'issued',verification_token CHAR(64) NOT NULL,metadata JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_certificate_no(certificate_no),UNIQUE KEY uq_pro_certificate_token(verification_token),CONSTRAINT fk_pro_certificate_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_certificate_template FOREIGN KEY(template_id) REFERENCES pro_certificate_templates(id) ON DELETE SET NULL,CONSTRAINT fk_pro_certificate_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_pro_certificate_person FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE SET NULL,CONSTRAINT fk_pro_certificate_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_campuses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,organizational_unit_id BIGINT UNSIGNED NULL,code VARCHAR(100) NOT NULL,name VARCHAR(255) NOT NULL,address TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_campus_code(institution_id,code),CONSTRAINT fk_pro_campus_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_campus_unit FOREIGN KEY(organizational_unit_id) REFERENCES organizational_units(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_campus_memberships (campus_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,role_code VARCHAR(50) NOT NULL DEFAULT 'member',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(campus_id,person_id,role_code),CONSTRAINT fk_pro_campus_member_campus FOREIGN KEY(campus_id) REFERENCES pro_campuses(id) ON DELETE CASCADE,CONSTRAINT fk_pro_campus_member_person FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_ai_assessment_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,test_id INT NULL,job_type VARCHAR(50) NOT NULL,model_name VARCHAR(150) NOT NULL DEFAULT 'qwen3:1.7b',prompt_version VARCHAR(50) NOT NULL DEFAULT 'v1',input_text LONGTEXT NOT NULL,output_json LONGTEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',requires_approval TINYINT(1) NOT NULL DEFAULT 1,approved_by INT NULL,approved_at DATETIME NULL,error_message TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,CONSTRAINT fk_pro_ai_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_ai_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE SET NULL,CONSTRAINT fk_pro_ai_approver FOREIGN KEY(approved_by) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_examiner_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,examiner_person_id BIGINT UNSIGNED NULL,examiner_admin_id INT NULL,scope_type VARCHAR(40) NOT NULL DEFAULT 'test',scope_id BIGINT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'assigned',assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,CONSTRAINT fk_pro_examiner_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE,CONSTRAINT fk_pro_examiner_person FOREIGN KEY(examiner_person_id) REFERENCES people(id) ON DELETE SET NULL,CONSTRAINT fk_pro_examiner_admin FOREIGN KEY(examiner_admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_moderation_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,student_id INT NULL,answer_ref VARCHAR(120) NULL,primary_examiner_id BIGINT UNSIGNED NULL,moderator_id BIGINT UNSIGNED NULL,original_mark DECIMAL(10,2) NULL,moderated_mark DECIMAL(10,2) NULL,decision VARCHAR(40) NOT NULL DEFAULT 'pending',reason TEXT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_pro_moderation_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE,CONSTRAINT fk_pro_moderation_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_pro_moderation_examiner FOREIGN KEY(primary_examiner_id) REFERENCES people(id) ON DELETE SET NULL,CONSTRAINT fk_pro_moderation_moderator FOREIGN KEY(moderator_id) REFERENCES people(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_mark_appeals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT NOT NULL,student_id INT NULL,moderation_review_id BIGINT UNSIGNED NULL,reason TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'submitted',decision TEXT NULL,decided_by INT NULL,decided_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_pro_appeal_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE CASCADE,CONSTRAINT fk_pro_appeal_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_pro_appeal_review FOREIGN KEY(moderation_review_id) REFERENCES pro_moderation_reviews(id) ON DELETE SET NULL,CONSTRAINT fk_pro_appeal_decider FOREIGN KEY(decided_by) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_corporate_assessments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,test_id INT NULL,assessment_code VARCHAR(100) NOT NULL,name VARCHAR(255) NOT NULL,assessment_type VARCHAR(60) NOT NULL DEFAULT 'recruitment',department VARCHAR(180) NULL,role_title VARCHAR(180) NULL,pass_score DECIMAL(6,2) NULL,ranking_enabled TINYINT(1) NOT NULL DEFAULT 1,status VARCHAR(30) NOT NULL DEFAULT 'draft',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_corp_code(institution_id,assessment_code),CONSTRAINT fk_pro_corp_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_corp_test FOREIGN KEY(test_id) REFERENCES tests(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_corporate_candidates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,corporate_assessment_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NULL,external_ref VARCHAR(150) NULL,application_status VARCHAR(50) NOT NULL DEFAULT 'invited',score DECIMAL(10,2) NULL,percentile DECIMAL(7,3) NULL,outcome VARCHAR(50) NULL,invited_at DATETIME NULL,completed_at DATETIME NULL,metadata JSON NULL,CONSTRAINT fk_pro_corp_candidate_assessment FOREIGN KEY(corporate_assessment_id) REFERENCES pro_corporate_assessments(id) ON DELETE CASCADE,CONSTRAINT fk_pro_corp_candidate_person FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_coding_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id INT NOT NULL,language_set JSON NOT NULL,starter_code LONGTEXT NULL,time_limit_ms INT UNSIGNED NOT NULL DEFAULT 3000,memory_limit_mb INT UNSIGNED NOT NULL DEFAULT 256,scoring_mode VARCHAR(30) NOT NULL DEFAULT 'test_cases',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_coding_question(question_id),CONSTRAINT fk_pro_coding_question FOREIGN KEY(question_id) REFERENCES new_questions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_coding_test_cases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,coding_question_id BIGINT UNSIGNED NOT NULL,input_data LONGTEXT NULL,expected_output LONGTEXT NOT NULL,hidden TINYINT(1) NOT NULL DEFAULT 1,points DECIMAL(8,2) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,CONSTRAINT fk_pro_coding_case_question FOREIGN KEY(coding_question_id) REFERENCES pro_coding_questions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_coding_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,coding_question_id BIGINT UNSIGNED NOT NULL,student_id INT NULL,attempt_id INT NULL,language VARCHAR(50) NOT NULL,source_code LONGTEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'queued',score DECIMAL(10,2) NOT NULL DEFAULT 0,max_score DECIMAL(10,2) NOT NULL DEFAULT 0,runtime_ms INT NULL,memory_kb INT NULL,output_text LONGTEXT NULL,error_text LONGTEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,CONSTRAINT fk_pro_coding_submission_question FOREIGN KEY(coding_question_id) REFERENCES pro_coding_questions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_coding_submission_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_pro_coding_submission_attempt FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pro_coding_test_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,submission_id BIGINT UNSIGNED NOT NULL,test_case_id BIGINT UNSIGNED NOT NULL,passed TINYINT(1) NOT NULL DEFAULT 0,actual_output LONGTEXT NULL,runtime_ms INT NULL,error_text TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pro_coding_case_result(submission_id,test_case_id),CONSTRAINT fk_pro_coding_result_submission FOREIGN KEY(submission_id) REFERENCES pro_coding_submissions(id) ON DELETE CASCADE,CONSTRAINT fk_pro_coding_result_case FOREIGN KEY(test_case_id) REFERENCES pro_coding_test_cases(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO pro_feature_catalog(feature_code,name,description) VALUES
