('multi_campus','Multi-Campus Administration','Central administration across campuses.'),
('ai_assessment','AI Assessment Suite','Offline AI authoring and assessment assistance.'),
('examiner_moderation','Examiner & Moderation','Examiner assignment, moderation and appeals.'),
('corporate_assessment','Corporate Assessment','Recruitment, competency and employee assessments.'),
('coding_assessment','Coding Assessments','Programming questions and controlled local runners.');